"""Only for the bundled synthetic fixtures. Production parsing is generated by Claude per case.

SOURCE_NAMES is injected by scripts/demo.py. records/emit are provided by the sandbox worker.
"""
import re
import xml.etree.ElementTree as ET

for sid, name in SOURCE_NAMES.items():  # noqa: F821
    rows = list(records(sid))  # noqa: F821 -- Tiny synthetic fixtures only; real parsers must stream.

    def output(fields, start, end):
        emit(fields, [{"source_id": sid, "start": start, "end": end}])  # noqa: F821

    if name == "nginx.log":
        pattern = re.compile(r'^(\S+) - - \[([^]]+)\] "(\S+) (\S+) HTTP/1.1" (\d+) .*request_id=(\S+)$')
        for n, line in rows:
            match = pattern.match(line)
            if match:
                ip, time, method, uri, status, request = match.groups()
                output({"event_kind": "nginx", "time_original": time, "ip": ip, "method": method,
                        "uri": uri, "status": int(status), "request_id": request, "parse_status": "ok"}, n, n)
            else:
                output({"parse_status": "failed", "message": line}, n, n)
    elif name == "java.log":
        events = []
        for n, line in rows:
            if re.match(r"^\d{4}-\d\d-\d\dT", line):
                events.append([n, n, line])
            elif events:
                events[-1][1] = n
                events[-1][2] += "\n" + line
            else:
                output({"parse_status": "failed", "message": line}, n, n)
        for start, end, message in events:
            request = re.search(r"request_id=(\S+)", message)
            output({"event_kind": "java", "time_original": message.split()[0], "message": message,
                    "request_id": request.group(1) if request else None, "parse_status": "ok"}, start, end)
    elif name == "iis.log":
        fields = []
        for n, line in rows:
            if line.startswith("#Fields:"):
                fields = line.split()[1:]
            elif line and not line.startswith("#"):
                values = dict(zip(fields, line.split()))
                output({"event_kind": "iis", "time_original": values["date"] + "T" + values["time"] + "Z",
                        "ip": values["c-ip"], "status": int(values["sc-status"]), "uri": values["cs-uri-stem"],
                        "parse_status": "ok"}, n, n)
    elif name == "windows.xml":
        root = ET.fromstring("\n".join(text for _, text in rows))
        ns = {"e": "http://schemas.microsoft.com/win/2004/08/events/event"}
        for event in root.findall("e:Event", ns):
            data = {node.attrib["Name"]: node.text for node in event.findall("e:EventData/e:Data", ns)}
            output({"event_kind": "windows", "event_id": int(event.findtext("e:System/e:EventID", namespaces=ns)),
                    "ip": data.get("IpAddress"), "message": data,
                    "time_original": event.find("e:System/e:TimeCreated", ns).attrib["SystemTime"],
                    "parse_status": "ok"}, rows[0][0], rows[-1][0])
